package co.edu.umb.boleteria.web;
import co.edu.umb.boleteria.service.*;import co.edu.umb.boleteria.web.dto.*;import co.edu.umb.boleteria.domain.Reserva;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/reservas") public class ReservaController {final ReservaFacade facade;final ReservaService service;public ReservaController(ReservaFacade f,ReservaService s){facade=f;service=s;}@PostMapping public ResponseEntity<ReservaDto> crear(@Valid @RequestBody CrearReservaRequest r){return ResponseEntity.status(201).body(facade.crear(r.localidadId(),r.usuarioId(),r.cantidad()));}@PostMapping("/{id}/confirmar") public ReservaDto confirmar(@PathVariable UUID id){Reserva r=service.confirmar(id);return ReservaDto.of(r,"");}@DeleteMapping("/{id}") public ResponseEntity<Void> cancelar(@PathVariable UUID id){service.cancelar(id);return ResponseEntity.noContent().build();}}
